// The service description (PWS v0.5 discovery): what this server speaks and
// where its Spaces Repository is. Served at GET /service, the place the
// reference client (pws-client 0.105+) and FreeWallet read it from under a
// base server URL, and still at GET / for clients that follow the `Link`
// header from the root; written verbatim into every Space archive the
// export operation produces, so one builder.

export const SPEC_ID = "https://w3id.org/pws";
export const SPEC_VERSION = "0.5";
export const SPEC_URL = "https://w3c-ccg.github.io/portable-web-spaces-spec/";

// Open token list; a client ignores tokens it does not know. `export`
// advertises the Export and Import Space operations together.
export const FEATURES = [
  "spaces-repository",
  "listing",
  "collection-management",
  "space-management",
  "resource-metadata",
  "conditional-writes",
  "policies",
  "export",
];

export function serviceDescription(req) {
  return {
    url: `${req.base}/service`,
    specs: {
      [SPEC_ID]: [
        {
          version: SPEC_VERSION,
          url: SPEC_URL,
          spaces: `${req.base}/spaces/`,
          features: FEATURES,
        },
      ],
    },
    instance: {
      name: "was-server-aws",
      version: process.env.INSTANCE_VERSION ?? "0.0.0",
      source: "https://github.com/digitalcredentials/was-server-aws",
    },
  };
}
